def _r(id, ra, cov=None, scores=None, decision="keep", reasons="", fix="", unsupported=None, safety="pass", source="pass", clar=False):
    s = {"steps": 2, "ask_or_answer": 2, "constraints": 2, "actionable": 2, "plain": 2, "realistic_user": 2}
    if scores:
        s.update(scores)
    return {
        "id": id,
        "required_actions": ra,
        "covered": cov if cov is not None else [True] * len(ra),
        "needs_clarification": clar,
        "gates": {"source": source, "safety": safety, "duplicate": "pass"},
        "unsupported_claims": unsupported or [],
        "scores": s,
        "decision": decision,
        "reasons": reasons,
        "fix": fix,
    }

